uint256 totalUnderlying = trackedUnderlying + totalBorrows - totalReserves + VIRTUAL_RESERVE;
uint256 effectiveSupply = totalSupply + VIRTUAL_SUPPLY;
return (totalUnderlying * 1e18) / effectiveSupply;

